  bool RotateBuilding(int id){var before=run.Board.Copy();if(!run.Rotate(id))return false;Remember(before,id);return true;}
  bool PlaceBuilding(string kind,int x,int y,int rotation=0){var before=run.Board.Copy();if(!run.Place(kind,x,y,rotation))return false;Remember(before,run.Board.Nodes.Max(n=>n.Id));return true;}
  bool RemoveBuilding(int id){var before=run.Board.Copy();if(!run.Remove(id))return false;Remember(before,run.Board.Nodes.FirstOrDefault()?.Id??0);return true;}
  bool UndoBuilding(){var before=run.Board.Copy();if(!run.Undo())return false;Remember(before,selected);return true;}
