  IEnumerator Resolve(){long earned=0;for(int beat=1;beat<=8;beat++){if(!skipRequested)sound.Cue("beat");foreach(var e in result.Events.Where(e=>e.Beat==beat)){earned+=e.Credits;if(e.Credits>0&&!skipRequested){sound.Cue("cash");var n=run.Board.Nodes.Find(z=>z.Id==e.Source);if(n!=null){GameFeel.Burst(38+(n.X+.5f)*644/run.Board.Width,310+(n.Y+.4f)*644/run.Board.Height,FlatUI.Hex("#FFD572"),12,2);var t=Studio.Label(grid,"+"+e.Credits,(n.X+.5f)*720f/run.Board.Width-80,(n.Y+.12f)*1280f/run.Board.Height,160,110,24,Studio.Accent,TextAlignmentOptions.Center,true);if(!data.Profile.ReducedMotion)t.gameObject.AddComponent<FloatingNumber>();}}if(e.Reason=="shipment"&&!skipRequested)Pulse(e);}score.text="$"+earned.ToString("N0")+" · "+beat+"/8";var scorePulse=score.GetComponent<HudPulse>()??score.gameObject.AddComponent<HudPulse>();scorePulse.Punch();if(skipRequested)yield return null;else yield return new WaitForSeconds(data.Profile.ReducedMotion?.08f:data.Profile.Selected<3?.58f:.42f);}busy=false;sound.Cue(result.Credits>=run.Mission.Target?"win":"loss");Result();}
  void Pulse(FlowEvent e){if(data.Profile.ReducedMotion)return;var a=run.Board.Nodes.Find(n=>n.Id==e.Source);var b=run.Board.Nodes.Find(n=>n.Id==e.Target);if(a==null||b==null)return;var dot=FlatUI.Rect(root,"Flow",38+(a.X+.5f)*644f/run.Board.Width-10,310+(a.Y+.5f)*644f/run.Board.Height-10,20,20);var token=dot.gameObject.AddComponent<ResourceToken>();token.Kind=e.Kind;token.raycastTarget=false;StartCoroutine(Travel(dot,b.X-a.X,b.Y-a.Y));}
  IEnumerator Travel(RectTransform dot,int dx,int dy){var start=dot.anchoredPosition;float time=0;while(time<.28f){time+=Time.deltaTime;dot.anchoredPosition=start+new Vector2(dx*grid.rect.width/run.Board.Width,-dy*grid.rect.height/run.Board.Height)*Mathf.Clamp01(time/.28f);yield return null;}Destroy(dot.gameObject);}
  void Result(){screen="result";int stars=run.Stars(result.Credits);GameFeel.Celebrate(stars);var m=Studio.Modal(root,stars>0?"A CITY IN RHYTHM":"ONE CONNECTION AWAY",()=>{run=new CityRun(data.Profile.Selected,run.Board.Copy());Board();});Studio.StarRow(m,stars,220);var earnedNumber=Studio.Label(m,result.Credits.ToString("N0"),44,340,632,130,70,Studio.Accent,TextAlignmentOptions.Center,true);earnedNumber.gameObject.AddComponent<ResultNumber>().Target=result.Credits;Studio.Label(m,"CASH FROM YOUR CHAIN",44,480,632,45,23,Studio.Muted,TextAlignmentOptions.Center);string combos=string.Join(" · ",Campaign.Combos(run.Board,result));long reward=data.Profile.Credits-previousWallet;int sales=result.Events.Where(e=>e.Reason=="sale").Sum(e=>e.Count);Studio.Label(m,(result.Credits>previousBest?"NEW PERSONAL BEST · ":"")+sales+" SALES\n"+(reward>0?"+"+reward+" CITY COINS FROM NEW STARS":"BEST SAVED · REPLAYS ARE FREE"),44,838,632,83,24,Studio.Accent,TextAlignmentOptions.Center,true);Studio.Label(m,(stars==3?"A perfect network. Every beat mattered.":stars>0?"District progress saved. There is more to discover.":"No progress lost. Try a different route.")+"\n\n"+(combos==""?"Tip: connect both people and goods to each shop.":"COMBOS\n"+combos)+"\n\nTarget "+run.Mission.Target+"   ·   3 stars "+run.Mission.Par,44,575,632,245,25);Studio.Button(m,stars>0&&data.Profile.Selected!=71&&data.Profile.Selected!=83&&data.Profile.Selected<103?"NEXT CITY  →":"TRY AGAIN",44,930,632,132,()=>StartLevel(stars>0?Math.Min(data.Profile.Selected<72?71:data.Profile.Selected<84?83:103,data.Profile.Selected+1):data.Profile.Selected),true);Studio.Button(m,"DISTRICT MAP",44,1080,632,132,()=>Map(data.Profile.Selected/12));Probe();}
