  void Contracts(){Base("contracts");Studio.Header(root,"YOUR CITY KEEPS WORKING","Delivery desk","15 one-time commissions · 3 active routes at a time",Menu);for(int i=0;i<5;i++){int template=libraryPage*5+i;if(template>=15)break;var c=data.Contracts.Find(z=>z.Template==template);bool open=template<=data.Profile.Cleared/3;float y=270+i*147;Studio.Label(root,ContractDesk.Names[template],38,y,440,50,29,Studio.Accent,heavy:true);long ticks=DateTime.UtcNow.Ticks;string text=c==null?(open?ContractDesk.Duration(template)/60+" min route · +"+ContractDesk.Reward(template)+" credits":"Unlocks at "+template*3+" city clears"):c.Claimed?"Completed · reward recorded":ticks>=c.EndTicks?"Returned · ready to collect":"Returns in "+Math.Ceiling(TimeSpan.FromTicks(c.EndTicks-ticks).TotalMinutes)+" min";Studio.Label(root,text,38,y+54,450,68,25,Studio.Muted);var button=Studio.Button(root,c==null?"SEND":c.Claimed?"✓":"COLLECT",520,y,162,100,()=>{if(c==null){if(!ContractDesk.Send(data.Contracts,template,run,data.Profile,DateTime.UtcNow.Ticks)){message="Run a star-winning city first. At most three routes can travel.";Board();return;}}else ContractDesk.Claim(c,data.Profile,DateTime.UtcNow.Ticks);Save();Contracts();});button.interactable=open&&(c==null||!c.Claimed&&ticks>=c.EndTicks);}Studio.Button(root,"‹",38,1030,100,90,()=>{libraryPage=(libraryPage+2)%3;Contracts();});Studio.Label(root,(libraryPage+1)+" / 3",170,1040,380,70,27,Studio.Muted,TextAlignmentOptions.Center);Studio.Button(root,"›",582,1030,100,90,()=>{libraryPage=(libraryPage+1)%3;Contracts();});Studio.Button(root,"30 ACHIEVEMENTS",38,1150,644,90,()=>Achievements(0),true);}
