  void About(){var m=Studio.Modal(root,"CASHFLOW CHAINS",Menu);Studio.Label(m,"Version 1.0\n\nA small city. Smart connections.\n\n72 free core cities, with optional expansion districts, cosmetics and convenience purchases through Google Play. No forced ads or account signup.\n\nCash and city coins are fictional game values. Your progress is stored on this device; uninstalling may remove it.\n\nBy Zayn Virk\nSupport: zaynvirkk@gmail.com\n\nConsumable gems and tickets are stored on this device and do not restore across devices. Permanent purchases restore through Google Play.",44,230,632,820,28);Studio.Button(m,"BACK TO YOUR CITY",44,1090,632,135,Board,true);}
